generated.needfile:
unrelated.txt: unrelated.src
  cp {{in}} {{out}}

build/generated.txt: source.txt file(helper.py)
  python helper.py generate source.txt {{out}}

build/bundle.txt: build/generated.txt footer.txt file(helper.py)
  python helper.py bundle build/generated.txt footer.txt {{out}}

environment.needfile:
build/mode.txt: env(BUILD_MODE)
  python3 helper.py env {{out}}
unrelated.txt: unrelated.src
  cp {{in}} {{out}}

atomic.needfile:
@atomic
build/first.txt build/second.txt: source.txt
  python3 helper.py pair {{out[0]}} {{out[1]}}

unrelated.txt: unrelated.src
  cp {{in}} {{out}}
